def _pages(pages):
    if (not isinstance(pages,list) or len(pages)!=93
            or any(not isinstance(page,dict)
                   or type(page.get('page_number')) is not int
                   or page['page_number']!=number
                   or not isinstance(page.get('text'),str)
                   or sha256(page['text'].encode()).hexdigest()!=PAGE_TEXT_SHA256[number-1]
                   for number,page in enumerate(pages,1))):
        raise ValueError('MYSON whole original pages changed')

def qualify_native(raw,native,selected):
    expected={'ticker':'5314.TWO','symbol':'5314','company_name':'世紀*',
              'event_date':'2026-04-15','event_end_date':'2026-04-15',
              'event_time':'14:00','material_file_date':'2026-04-15',
              'filename':'531420260415E001.pdf','format':'pdf','language':'en'}
    if (not isinstance(selected,dict) or not isinstance(native,dict)
            or any(selected.get(k)!=value for k,value in expected.items())
            or not isinstance(raw,bytes) or len(raw)!=RAW_BYTES
            or sha256(raw).hexdigest()!=KNOWN_SHA
            or native.get('content_sha256')!=KNOWN_SHA
            or native.get('coverage_status')!='complete'
            or type(native.get('page_count')) is not int or native['page_count']!=93
            or native.get('empty_pages')!=[] or native.get('garbled_pages')!=[]):
        raise ValueError('MYSON MOPS original identity/format/coverage unqualified')
    _pages(native.get('pages'))
    return 'mixed'

def qualified_projection(pages):
    _pages(pages)
    for numbers in ROLE_PAGES.values():
        if sum(len(p['text']) for p in pages if p['page_number'] in numbers)>6000:
            raise ValueError('MYSON whole pages exceed role budget')
    used={n for numbers in ROLE_PAGES.values() for n in numbers}
    return {'role_projection_policy':'mops-qualified-whole-pages-v1',
            'role_page_allowlist':{str(role):list(numbers) for role,numbers in ROLE_PAGES.items()},
            'projection_excluded_pages':[n for n in range(1,94) if n not in used]}
